# Generated by build.py from recipe.yml for recipe smtp-send-despite-a-bad-recipient. Do not edit.
set -e
cd "$(dirname "$0")"
cat > minutes.eml <<'EOF'
From: app@example.com
To: ann@example.com, carol@elsewhere.org, bob@example.com, cy@example.com
Subject: Minutes of Tuesday's meeting

The minutes are on the team site.
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox cy@example.com:cypass --mailbox dee@example.com:deepass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com --mail-rcpt carol@elsewhere.org --mail-rcpt bob@example.com --mail-rcpt cy@example.com --mail-rcpt-allowfails -T minutes.eml -o /dev/null -w "%{response_code}\n" smtp://127.0.0.1:8080/example.com --next -sS --retry 10 --retry-all-errors --retry-delay 1 -o /dev/null -u cy@example.com:cypass "imap://127.0.0.1:8081/INBOX;UID=1" --next -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?ALL" --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX?ALL" --next -sS -u cy@example.com:cypass "imap://127.0.0.1:8081/INBOX?ALL"
kill $(jobs -p)
